import apiService from "./APIService";
import { UserParams } from "./types/user";

const getUser = (params: UserParams) => {
  return apiService.request("GET /users/" + params.username);
};

const getUserRepos = (params: UserParams) => {
  return apiService.request("GET /users/" + params.username + "/repos");
};

const getUserFollowers = (params: UserParams) => {
  return apiService.request("GET /users/" + params.username + "/followers");
};

const getUserFollowing = (params: UserParams) => {
  return apiService.request("GET /users/" + params.username + "/following");
};

export { getUser, getUserRepos, getUserFollowers, getUserFollowing };
