import { memo, useEffect, useState, useMemo, useCallback } from "react";
import { useParams } from "react-router-dom";
import { useTheme } from "@mui/material/styles";
import Box from "@mui/material/Box";
import Tab from "@mui/material/Tab";
import TabContext from "@mui/lab/TabContext";
import TabList from "@mui/lab/TabList";

import UserItem from "components/UserItem";
import RepoItem from "components/RepoItem";
import Loading from "components/Loading";
import { LocationIcon } from "assets/images";
import { useTypedSelector, useTypedDispatch } from "stores/store";
import { getUserData } from "stores/actions/user";
import { initialState } from "stores/user";
import { User, Repo } from "utils/types";

import * as S from "./styled";

const Detail = () => {
  let params = useParams();
  const theme = useTheme();
  const dispatch = useTypedDispatch();

  const [value, setValue] = useState("2");

  const { isLoading, data }: initialState = useTypedSelector(
    (state) => state.userState
  );

  const handleChange = useCallback(
    (event: React.SyntheticEvent, newValue: string) => {
      setValue(newValue);
    },
    [setValue]
  );

  const [repoCount, followerCount, followingCount] = useMemo(
    () => [data?.repos.length, data?.followers.length, data?.following.length],
    [data]
  );

  useEffect(() => {
    dispatch(getUserData({ username: params.id || "" }));
  }, [dispatch, params]);

  if (isLoading) {
    return (
      <S.Wrap>
        <Loading />
      </S.Wrap>
    );
  }

  return (
    <S.Detail>
      <S.UserDetail>
        <S.Avatar src={data?.user.avatar_url} alt="avatar" />
        <S.Name style={{ color: theme.palette.text.primary }}>
          {data?.user.name}
        </S.Name>
        <S.Login style={{ color: theme.palette.text.primary }}>
          {data?.user.login}
        </S.Login>
        <S.Location style={{ color: theme.palette.text.primary }}>
          {data?.user.location && (
            <LocationIcon style={{ color: theme.palette.text.primary }} />
          )}{" "}
          {data?.user.location}
        </S.Location>
      </S.UserDetail>
      <S.UserTabs>
        <Box>
          <TabContext value={value}>
            <Box sx={{ borderBottom: 1, borderColor: "divider" }}>
              <TabList onChange={handleChange}>
                <Tab label={`Repositories (${repoCount})`} value="1" />
                <Tab label={`Followers (${followerCount})`} value="2" />
                <Tab label={`Followings (${followingCount})`} value="3" />
              </TabList>
            </Box>
            <S.CustomTabPanel value="1">
              <S.ReposTab>
                {data?.repos.map((repo: Repo) => (
                  <RepoItem key={repo.name} repo={repo} />
                ))}
              </S.ReposTab>
            </S.CustomTabPanel>
            <S.CustomTabPanel value="2">
              <S.FollowersTab>
                {data?.followers.map((follower: User) => (
                  <UserItem
                    key={follower.login}
                    user={follower}
                    defaultFavorite={false}
                  />
                ))}
              </S.FollowersTab>
            </S.CustomTabPanel>
            <S.CustomTabPanel value="3">
              <S.FollowingTab>
                {data?.following.map((follower: User) => (
                  <UserItem
                    key={follower.login}
                    user={follower}
                    defaultFavorite={false}
                  />
                ))}
              </S.FollowingTab>
            </S.CustomTabPanel>
          </TabContext>
        </Box>
      </S.UserTabs>
    </S.Detail>
  );
};

export default memo(Detail);
