import { Dispatch } from "redux";

import {
  getUser,
  getUserRepos,
  getUserFollowers,
  getUserFollowing,
} from "services/UserService";

import { UserParams } from "services/types/user";

import * as types from "./../types/user";

const userLoading = (dispatch: Dispatch) => {
  dispatch({
    type: types.USER_LOADING,
    payload: true,
  });
};

export const getUserData =
  (params: UserParams) => async (dispatch: Dispatch) => {
    try {
      userLoading(dispatch);

      let userData = {};

      Promise.all([
        getUser(params),
        getUserRepos(params),
        getUserFollowers(params),
        getUserFollowing(params),
      ]).then((data) => {
        userData = {
          user: data[0].data,
          repos: data[1].data,
          followers: data[2].data,
          following: data[3].data,
        };
        dispatch({ type: types.USER_DATA, payload: userData });
      });
    } catch (error) {
      return Promise.reject(error);
    }
  };
