import { memo } from "react";
import { useTheme } from "@mui/material/styles";

import { Theme } from "utils/constants";
import { Repo } from "utils/types";
import { globalThemes } from "theme";

import * as S from "./styled";

type RepoItemProps = {
  repo: Repo;
};

const RepoItem = ({ repo }: RepoItemProps) => {
  const theme = useTheme();

  return (
    <S.RepoItem
      style={{
        boxShadow:
          theme.palette.mode === Theme.Light
            ? globalThemes.userItem.boxShadow.light
            : globalThemes.userItem.boxShadow.dark,
      }}
    >
      <S.RepoName style={{ color: theme.palette.text.primary }}>
        {repo.name}
      </S.RepoName>
    </S.RepoItem>
  );
};

export default memo(RepoItem);
